package com.srinu.otelpoc.customer.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.NoSuchElementException; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<ErrorBody> notFound(NoSuchElementException e){return ResponseEntity.status(404).body(new ErrorBody(Instant.now(),"NOT_FOUND",e.getMessage()));} @ExceptionHandler(Exception.class) ResponseEntity<ErrorBody> other(Exception e){return ResponseEntity.status(500).body(new ErrorBody(Instant.now(),"INTERNAL_ERROR","Unexpected error"));} record ErrorBody(Instant timestamp,String code,String message){} }
